{"path":"workflow.py","content":""""订单对账 v1：纯函数实现，仅使用标准库（csv/io/decimal 等）。"""
import csv
import io
import json
from decimal import Decimal, InvalidOperation


def _parse_amount_cents(raw):
    """把金额字符串解析为非负整数分；拒绝 NaN/Infinity/负数/超过两位小数。"""
    if raw is None:
        raise ValueError("missing amount")
    text = str(raw).strip()
    if text == "":
        raise ValueError("missing amount")
    try:
        value = Decimal(text)
    except InvalidOperation:
        raise ValueError("invalid amount: %s" % text)
    if not value.is_finite():
        raise ValueError("non-finite amount: %s" % text)
    if value.copy_sign(Decimal(1)).compare(value) != 0:
        raise ValueError("negative amount: %s" % text)
    exponent = value.as_tuple().exponent
    if not isinstance(exponent, int) or exponent < -2:
        raise ValueError("more than two decimals: %s" % text)
    cents = value.scaleb(2)
    if cents != cents.to_integral_value():
        raise ValueError("fractional cents: %s" % text)
    return int(cents)


def _read_rows(csv_string, required_headers):
    reader = csv.DictReader(io.StringIO(csv_string))
    header = reader.fieldnames
    if header is None:
        raise ValueError("missing CSV header")
    for name in required_headers:
        if name not in header:
            raise ValueError("missing column: %s" % name)
    return list(reader)


def _canonical(row, headers):
    return tuple((row.get(h) or "").strip() for h in headers)


def reconcile(orders_csv, refunds_csv, policy="v1", cutoff=None):
    """按 v1 契约对账。cutoff 在 v1 中保留但不生效（为后续版本预留）。"""
    order_headers = ["order_id", "customer", "amount", "status", "created_at"]
    refund_headers = ["refund_id", "order_id", "amount"]

    orders = {}
    order_first = {}
    for row in _read_rows(orders_csv, order_headers):
        canon = _canonical(row, order_headers)
        order_id = canon[0]
        if order_id == "":
            raise ValueError("empty order_id")
        if order_id in orders:
            if orders[order_id] == canon:
                continue  # 完全相同的重复行，只算一次
            raise ValueError("conflicting duplicate order: %s" % order_id)
        orders[order_id] = canon

    refunds = {}
    refund_first = {}
    for row in _read_rows(refunds_csv, refund_headers):
        canon = _canonical(row, refund_headers)
        refund_id = canon[0]
        if refund_id == "":
            raise ValueError("empty refund_id")
        if refund_id in refunds:
            if refunds[refund_id] == canon:
                continue
            raise ValueError("conflicting duplicate refund: %s" % refund_id)
        refunds[refund_id] = canon

    # 校验退款引用并累计
    refund_by_order = {}
    for refund_id in sorted(refunds):
        _, order_id, amount_text = refunds[refund_id]
        if order_id not in orders:
            raise ValueError("refund %s references unknown order %s" % (refund_id, order_id))
        if orders[order_id][3] != "paid":
            raise ValueError("refund %s references non-paid order %s" % (refund_id, order_id))
        cents = _parse_amount_cents(amount_text)
        refund_by_order[order_id] = refund_by_order.get(order_id, 0) + cents

    for order_id, refund_total in refund_by_order.items():
        paid = _parse_amount_cents(orders[order_id][2])
        if refund_total > paid:
            raise ValueError(
                "refunds (%d) exceed paid (%d) for order %s" % (refund_total, paid, order_id)
            )

    order_rows = []
    customer_net = {}
    total_paid = 0
    total_refund = 0
    for order_id in sorted(orders):
        _, customer, amount_text, status, _ = orders[order_id]
        if status != "paid":
            continue  # cancelled 等非 paid 订单不入结果
        paid = _parse_amount_cents(amount_text)
        refund = refund_by_order.get(order_id, 0)
        net = paid - refund
        order_rows.append({
            "order_id": order_id,
            "customer": customer,
            "paid_cents": paid,
            "refund_cents": refund,
            "net_cents": net,
        })
        customer_net[customer] = customer_net.get(customer, 0) + net
        total_paid += paid
        total_refund += refund

    customers = [
        {"customer": name, "net_cents": customer_net[name]}
        for name in sorted(customer_net)
    ]
    return {
        "orders": order_rows,
        "customers": customers,
        "totals": {
            "paid_cents": total_paid,
            "refund_cents": total_refund,
            "net_cents": total_paid - total_refund,
        },
    }


def export_bundle(result):
    """把对账结果导出为可序列化的简单 bundle（v1 仅提供最小实现）。"""
    return {"summary.json": json.dumps(result.get("totals", {}), sort_keys=True)}
"}
